question.answer:
import java.util.HashMap;
import java.util.Map;

/**
 * Week 3. Pattern: hash map lookup.
 * <p>
 * A reconciliation clerk knows two transfers (amounts in kobo) add up to {@code target}. Return the indices
 * {@code [i, j]} with {@code i < j} of the first such pair found scanning left to right (smallest {@code j}),
 * or an empty array if there is none. Aim for O(n) time.
 */
public final class TwoSumTransfers {

    private TwoSumTransfers() {
    }

    public static int[] find(long[] amounts, long target) {
        //>>
        Map<Long, Integer> seen = new HashMap<>();
        for (int j = 0; j < amounts.length; j++) {
            Integer i = seen.get(target - amounts[j]);
            if (i != null) {
                return new int[] {i, j};
            }
            seen.putIfAbsent(amounts[j], j);
        }
        return new int[0];
        //<<
    }
}

testcode.text:
// 200,000 amounts: an O(n^2) answer is too slow here (3-second budget).
long[] amounts = new long[200_000];
for (int i = 0; i < amounts.length; i++) amounts[i] = i * 2L;
amounts[amounts.length - 1] = 1;
within(3000, () -> TwoSumTransfers.find(amounts, 3));

