question.answer:
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Week 5. Pattern: hash set with sequence starts.
 * <p>
 * Given the (unsorted, possibly repeated) dates on which a customer transacted, return the length of the
 * longest run of consecutive calendar days. Aim for O(n) rather than sorting.
 */
public final class LongestActiveStreak {

    private LongestActiveStreak() {
    }

    public static int longest(List<LocalDate> days) {
        //>>
        Set<LocalDate> set = new HashSet<>(days);
        int best = 0;
        for (LocalDate d : set) {
            if (set.contains(d.minusDays(1))) {
                continue;                          // not the start of a streak
            }
            int length = 1;
            while (set.contains(d.plusDays(length))) {
                length++;
            }
            best = Math.max(best, length);
        }
        return best;
        //<<
    }
}

testcode.text:
System.out.println(LongestActiveStreak.longest(List.of(
        LocalDate.parse("2026-03-02"), LocalDate.parse("2026-02-28"), LocalDate.parse("2026-03-01"),
        LocalDate.parse("2026-03-10"), LocalDate.parse("2026-02-27"), LocalDate.parse("2026-03-01"))));

// 100,001 dates, 3-second budget: sorting works, but aim for linear time.
List<LocalDate> days = new ArrayList<>();
LocalDate start = LocalDate.parse("2000-01-01");
for (int i = 0; i < 100_000; i++) days.add(start.plusDays(i * 2L));
days.add(start.plusDays(1));
within(3000, () -> LongestActiveStreak.longest(days));

